with valid_employees as (select * from employees where full_name like '%Jac%'), employees_stats as (select case when salary >= 153000 then 'high' when salary >= 80000 then 'mid' else 'low' end salary_bucket, sum(case when job_title = 'Manager' then 1 else 0 end) manager_count, sort_array(collect_set(job_title)) job_title_list from valid_employees group by case when salary >= 153000 then 'high' when salary >= 80000 then 'mid' else 'low' end) select salary_bucket, manager_count, job_title_list from employees_stats where manager_count >= 42;
